import{_ as e}from"./chunks/tray-panel.kylWqXfw.js";import{_ as r,o as t,c as l,a3 as o}from"./chunks/framework.BTt0kA_k.js";const _=JSON.parse('{"title":"托盘小面板","description":"","frontmatter":{},"headers":[],"relativePath":"user/use/panel.md","filePath":"user/use/panel.md"}'),i={name:"user/use/panel.md"};function s(n,a,p,h,c,d){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="托盘小面板" tabindex="-1">托盘小面板 <a class="header-anchor" href="#托盘小面板" aria-label="Permalink to &quot;托盘小面板&quot;">​</a></h1><p>macOS 状态栏中的 RelayPulse 图标是日常查看状态的入口。主窗口关闭后，应用仍可按设置在后台工作。</p><h2 id="打开和关闭面板" tabindex="-1">打开和关闭面板 <a class="header-anchor" href="#打开和关闭面板" aria-label="Permalink to &quot;打开和关闭面板&quot;">​</a></h2><ul><li>单击状态栏图标打开或收起小面板。</li><li>点击面板外部收起面板。</li><li>点击面板右上角“设置”打开通用设置。</li><li>点击“查看全部”进入主窗口的站点管理。</li><li>右键状态栏图标，可以选择“打开状态面板”或“退出 RelayPulse”。</li></ul><p>退出应用会停止后台任务；关闭主窗口后的行为由<a href="./settings.html">通用设置</a>控制。</p><h2 id="查看模型状态和耗时" tabindex="-1">查看模型状态和耗时 <a class="header-anchor" href="#查看模型状态和耗时" aria-label="Permalink to &quot;查看模型状态和耗时&quot;">​</a></h2><p>面板按站点分组，展示模型名称、所属站点、当前健康状态，以及“首 Token / 总耗时”。最多显示 <strong>3 个模型</strong>；底部“显示 x/y 个模型”表示当前可见数量与全部数量。</p><p>模型缺少某个耗时数据时显示 <code>—</code>。例如 <code>— / 2.10 s</code> 表示有总耗时数据，但没有首 Token 数据。状态判定和计时口径见<a href="./probes.html#健康状态怎样判定">探针说明</a>。</p><p>没有正式结果时显示“等待探测”；达到健康判定阈值前可能显示“待确认”。可以在“运行 → 探测记录”核对具体请求结果。</p><figure class="guide-figure"><p><a href="/RelayPulse/screenshots/user/tray-panel.webp"><img src="'+e+'" alt="实际托盘小面板中正常、偏慢、不可用状态与请求耗时"></a></p><figcaption>① 正常；② 偏慢；③ 不可用。右侧为首 Token / 总耗时；缺少的指标显示“—”。本例已暂停周期探测，底部显示“未启用周期探测”。</figcaption></figure><h2 id="立即探测" tabindex="-1">立即探测 <a class="header-anchor" href="#立即探测" aria-label="Permalink to &quot;立即探测&quot;">​</a></h2><p>点击右上角刷新图标“立即探测”，会发起正式探测，而不只是重新读取界面数据，因此可能产生 API 用量。正在探测时，该按钮会显示忙碌状态。</p><p>底部的“最近完成”表示最近一轮探测完成时间；“下次”表示已安排的周期探测时间。显示“未启用周期探测”时，检查<a href="./../faq.html#为什么没有自动探测">自动探测条件</a>。</p><h2 id="图标颜色代表什么" tabindex="-1">图标颜色代表什么 <a class="header-anchor" href="#图标颜色代表什么" aria-label="Permalink to &quot;图标颜色代表什么&quot;">​</a></h2><p>状态栏图标显示蓝色，表示当前存在已启用、可参与面板展示的站点和模型。模型是否健康，要看面板内每一行的状态。</p><p>需要隐藏状态栏图标时，在“配置 → 通用设置”关闭“显示状态栏图标”。该开关只控制图标，后台探测仍按其自身条件运行。</p>',16)])])}const m=r(i,[["render",s]]);export{_ as __pageData,m as default};
